// replica holds EUR/USD = 1.0800 at version 6; apply() stores only a greater version
apply(new RateEvent("EUR/USD", "1.0950", 7));
apply(new RateEvent("EUR/USD", "1.0800", 6));   // redelivered
Order order = checkout.price("EUR/USD");
System.out.println(order.rate() + " v" + order.rateVersion());

BigDecimal price(String pair, BigDecimal amount) {
    BigDecimal rate = replica.get(pair);
    return amount.multiply(rate);
}
